	if preferredSessionID == "" {
		return nil
	}
	if _, ok := findTrailRestoredSession(sessions, preferredSessionID); ok {
		return nil
	}
	return fmt.Errorf("session %q was not found in the restored checkpoint", preferredSessionID)
}

